.favorites-page{font-weight:400}.favorites-page h1,.favorites-page h2,.favorites-page strong,.favorites-page b{font-weight:400!important}.favorites-heading{margin:0 0 26px;text-align:center}.favorites-heading h1{margin:0 0 9px;color:#2e2528;font-size:clamp(1.9rem,4vw,2.65rem);line-height:1.15;letter-spacing:-.035em}.favorites-heading p,.favorites-empty p{font-size:1.08rem;line-height:1.6}.favorites-heading p{margin:0;color:var(--muted)}.favorites-grid-controls{display:flex;justify-content:flex-end;align-items:center;gap:3px;width:max-content;margin:0 0 12px auto;padding:2px;border:1px solid var(--line);border-radius:10px;background:#fff}.favorites-grid-controls[hidden]{display:none!important}.favorites-column-button{width:32px;height:30px;display:grid;place-items:center;padding:0;border:0;border-radius:7px;background:transparent;color:#716664;cursor:pointer;transition:background .15s,color .15s,box-shadow .15s}.favorites-column-button:hover{background:#fff4f6;color:var(--accent-dark)}.favorites-column-button.is-active{background:#fbe8ed;color:var(--accent-dark);box-shadow:inset 0 0 0 1px #f0c9d3}.favorites-column-button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}.favorites-column-button>span{display:flex;align-items:stretch;justify-content:center;gap:2px;width:22px;height:16px}.favorites-column-button i{flex:1;border:1px solid currentColor;border-radius:2px;background:currentColor;opacity:.78}@media(min-width:1200px) and (max-width:1399px){.favorites-grid[data-columns="4"]{grid-template-columns:repeat(3,minmax(0,1fr))}.favorites-grid-controls [data-catalog-columns="4"]{display:none}}.favorites-grid{margin-bottom:30px}.favorites-grid[hidden]{display:none}.favorites-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:230px;padding:42px 20px;background:linear-gradient(135deg,#fff9fa,#fff1f4 55%,#fff8f9);border:1px solid #f4dce2;border-radius:18px;text-align:center}.favorites-empty[hidden]{display:none}.favorites-empty-heart{display:block;color:#e34c70;font-size:3rem;line-height:1}.favorites-empty h2{margin:10px 0 7px;color:#3b3033;font-size:1.2rem}.favorites-empty p{max-width:560px;margin:0;color:var(--muted)}@media(max-width:520px){.favorites-heading p,.favorites-empty p{font-size:1rem}.favorites-empty{min-height:200px;padding:34px 18px}}
</style>
<script>
(()=>{const page=document.querySelector('[data-favorites-page]');if(!page)return;const grid=page.querySelector('.favorites-grid'),controls=page.querySelector('.favorites-grid-controls'),key='giftcheta:favorites-columns:v1',allowsFour=()=>!window.matchMedia('(min-width: 1200px) and (max-width: 1399px)').matches;if(!grid||!controls)return;let requested=4;try{requested=Number(localStorage.getItem(key))||4}catch{}function apply(value,save=true){requested=Math.max(1,Math.min(4,Number(value)||4));const columns=Math.min(allowsFour()?4:3,requested);grid.dataset.columns=String(columns);controls.querySelectorAll('[data-favorites-columns]').forEach(button=>{const active=Number(button.dataset.favoritesColumns)===columns;button.classList.toggle('is-active',active);button.setAttribute('aria-pressed',String(active))});if(save){try{localStorage.setItem(key,String(requested))}catch{}}}apply(requested,false);window.addEventListener('resize',()=>apply(requested,false));document.addEventListener('click',event=>{const button=event.target.closest('[data-favorites-columns]');if(button&&page.contains(button))apply(button.dataset.favoritesColumns)});function syncVisibility(){controls.hidden=!(window.GiftchetaFavorites?.read().length)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',syncVisibility,{once:true});else syncVisibility();window.addEventListener('giftcheta:favorites-changed',event=>{controls.hidden=!(event.detail?.items?.length)});})();
</script>
